from _lib import *
u1=U("verbing","Verb + -ing or verb + to","B1",
 "Some verbs are followed by -ing (enjoy, avoid, finish, mind, suggest), others by to + base form (want, decide, hope, plan, agree). Learn them in pairs with the verb.",
 "কিছু verb-এর পরে -ing বসে (enjoy, avoid, finish), আর কিছু verb-এর পরে to + verb (want, decide, plan)। verb দেখে মুখস্থ করুন।",
 [("Verb + -ing","enjoy / avoid / finish / mind / suggest / keep + doing"),("Verb + to","want / decide / hope / plan / agree / refuse / afford + to do"),("Verb + object + to","ask / tell / want / expect + someone + to do")],
 [("Likes, avoiding and finishing usually take -ing.","enjoy, avoid, finish, mind-এর পরে -ing।","I enjoy working with this team."),
  ("Plans, wishes and decisions usually take to.","ইচ্ছা, পরিকল্পনা, সিদ্ধান্তে to + verb।","Rafi decided to rent a flat in Mirpur."),
  ("Suggest takes -ing or a that-clause, never an object + to.","suggest + someone + to ভুল।","She suggested meeting on Sunday."),
  ("Would you mind + -ing is a polite request.","ভদ্র অনুরোধ: Would you mind + -ing?","Would you mind closing the window?"),
  ("Want / ask / expect + person + to.","কাউকে কিছু করতে বলা: person + to।","My boss wants me to finish the report today.")],
 ["enjoy","avoid","decide","suggest","mind","afford"],
 [("I enjoy to work here.","I enjoy working here.","Enjoy is followed by -ing.","enjoy-এর পরে -ing।"),
  ("He suggested me to apply.","He suggested that I apply. / He suggested applying.","Suggest does not take object + to.","suggest + person + to হয় না।"),
  ("I want that you come.","I want you to come.","Want + person + to, not a that-clause.","want-এর পরে that-clause নয়।")],
 [C("Talking about your job.","I really enjoy ___ with clients.",["working","to work","work","worked"],"working","Enjoy + -ing."),
  C("Rafi's plans.","Rafi hopes ___ a promotion next year.",["to get","getting","get","for getting"],"to get","Hope + to."),
  T("A polite request in the office.","Would you mind ___ (send) me the file again?","send",["sending"],"Would you mind + -ing."),
  T("Money talk.","We can't afford ___ (buy) a car this year.","buy",["to buy"],"Afford + to."),
  F("Pick the correct sentence.",["My manager suggested me to take a break.","My manager suggested taking a break.","My manager suggested to take a break.","My manager suggested take a break."],"My manager suggested taking a break.","Suggest + -ing."),
  B("আম্মা চান আমি তাড়াতাড়ি বাসায় ফিরি।",["My mother wants me to come home early.","My mother wants that I come home early.","My mother wants me coming home early.","My mother wants I come home early."],"My mother wants me to come home early.","Want + person + to."),
  C("Traffic in Dhaka.","I try to avoid ___ during rush hour.",["travelling","to travel","travel","travelled"],"travelling","Avoid + -ing."),
  C("A tough client.","The client refused ___ the extra charge.",["to pay","paying","pay","for paying"],"to pay","Refuse + to.",True),
  F("Pick the correct sentence.",["Have you finished to write the proposal?","Have you finished writing the proposal?","Have you finished write the proposal?","Have you finished for writing the proposal?"],"Have you finished writing the proposal?","Finish + -ing.",True)])
u2=U("meaning","Stop, remember, try: meaning changes","B2",
 "A few verbs take both forms with different meanings. Remember / forget + to = a duty still to do; + -ing = a memory of the past. Stop + -ing = quit the action; stop + to = pause in order to do something. Try + to = make an effort; try + -ing = test a method.",
 "stop, remember, forget, try-এর পরে -ing আর to দুটোই বসে, কিন্তু অর্থ বদলে যায়।",
 [("Remember / forget","+ to do = a task to do · + doing = a past memory"),("Stop","+ doing = quit · + to do = stop in order to do"),("Try","+ to do = attempt something hard · + doing = experiment")],
 [("Remember to = don't forget a task.","কাজটা করতে মনে রাখা।","Remember to lock the door when you leave."),
  ("Remember + -ing = a memory.","অতীতের স্মৃতি।","I remember meeting him at the Rajshahi fair."),
  ("Stop + -ing = quit.","কাজটা বন্ধ করা।","He stopped smoking last year."),
  ("Stop + to = pause in order to do.","কিছু করার জন্য থামা।","We stopped to buy tea on the highway."),
  ("Try + -ing = test a solution.","উপায় হিসেবে চেষ্টা করে দেখা।","If the laptop freezes, try restarting it.")],
 ["remember","forget","stop","try","regret"],
 [("Remember locking the office tonight.","Remember to lock the office tonight.","A future duty needs to.","ভবিষ্যতের কাজ = to।"),
  ("We stopped drinking tea at a stall on the way.","We stopped to drink tea at a stall on the way.","Pausing a journey in order to drink needs to.","কিছু করার জন্য থামলে to।"),
  ("I'll never forget to see the sea for the first time.","I'll never forget seeing the sea for the first time.","A memory needs -ing.","স্মৃতি = -ing।")],
 [C("Leaving the office.","Please remember ___ the lights before you go.",["to switch off","switching off","switch off","switched off"],"to switch off","A task still to do."),
  C("Old memories.","I remember ___ to Cox's Bazar with my family as a child.",["going","to go","go","gone"],"going","A past memory."),
  T("Health.","My father stopped ___ (eat) sweets after his check-up.","eat",["eating"],"Quit the habit: stop + -ing."),
  T("A road trip.","On the way to Sylhet, we stopped ___ (have) lunch.","have",["to have"],"Pause in order to do: stop + to."),
  F("Pick the correct sentence.",["The Wi-Fi is down. Try to restarting the router.","The Wi-Fi is down. Try restarting the router.","The Wi-Fi is down. Try restart the router.","The Wi-Fi is down. Try for restarting the router."],"The Wi-Fi is down. Try restarting the router.","Testing a solution: try + -ing."),
  B("আমি ওকে ফোন করতে ভুলে গেছি।",["I forgot to call him.","I forgot calling him.","I forgot call him.","I forgot for calling him."],"I forgot to call him.","Forgot the task: forget + to."),
  C("A hard task.","I tried ___ the file, but it was too large.",["to open","opening","open","opened"],"to open","An attempt that failed: try + to.",True),
  C("A formal apology.","We regret ___ you that your application was unsuccessful.",["to inform","informing","inform","informed"],"to inform","Regret + to = sorry to say now.",True)])
u3=U("preping","Preposition + -ing","B2",
 "After a preposition, a verb takes the -ing form. This includes 'to' when it is a preposition: look forward to, be used to, object to.",
 "preposition-এর পরে verb এলে -ing হয়। look forward to, be used to-তে to একটা preposition, তাই পরে -ing।",
 [("Preposition + -ing","interested in / good at / before / after / without / instead of + doing"),("to as a preposition","look forward to / be used to / get used to / object to + doing")],
 [("After in, at, of, about, for, without: -ing.","preposition-এর পরে -ing।","She's good at handling difficult clients."),
  ("Before / after + -ing.","আগে/পরে + -ing।","Check the figures before sending the report."),
  ("Look forward to + -ing.","অপেক্ষায় থাকা: to + -ing।","I look forward to hearing from you."),
  ("Be / get used to + -ing = be familiar with.","অভ্যস্ত হওয়া।","Rafi is getting used to living alone in Dhaka."),
  ("Used to + base = past habit (different structure).","অতীত অভ্যাস: used to + base।","I used to live in Rajshahi.")],
 ["look forward to","be used to","instead of","without","interested in"],
 [("I look forward to meet you.","I look forward to meeting you.","To is a preposition here.","এখানে to preposition, তাই -ing।"),
  ("He left without say goodbye.","He left without saying goodbye.","Without + -ing.","without-এর পরে -ing।"),
  ("I am used to wake up early.","I am used to waking up early.","Be used to + -ing.","be used to + -ing।")],
 [C("Ending an email.","I look forward to ___ from you.",["hearing","hear","heard","be hearing"],"hearing","Look forward to + -ing."),
  C("A job interview.","I'm interested in ___ more about this role.",["learning","to learn","learn","learnt"],"learning","In + -ing."),
  T("Office advice.","Always read the contract before ___ (sign) it.","sign",["signing"],"Before + -ing."),
  T("Rafi's new life.","After six months, Rafi is used to ___ (take) the bus to Gulshan.","take",["taking"],"Be used to + -ing."),
  F("Pick the correct sentence.",["Instead of call, she sent a message.","Instead of calling, she sent a message.","Instead of to call, she sent a message.","Instead to calling, she sent a message."],"Instead of calling, she sent a message.","Instead of + -ing."),
  B("আমি আগে রাজশাহীতে থাকতাম।",["I used to live in Rajshahi.","I am used to living in Rajshahi.","I used to living in Rajshahi.","I was used to live in Rajshahi."],"I used to live in Rajshahi.","Past habit: used to + base."),
  C("A meeting.","Does anyone object to ___ the meeting to Thursday?",["moving","move","moved","have moved"],"moving","Object to + -ing.",True),
  F("Pick the correct sentence.",["Thank you for help me with the slides.","Thank you for helping me with the slides.","Thank you to help me with the slides.","Thank you for to help me with the slides."],"Thank you for helping me with the slides.","For + -ing.",True)])
save("gerunds","Gerunds and infinitives",
 "Should it be 'to do' or 'doing'? Bangla doesn't make this choice, so learners often guess. Learn which verbs take which form, the verbs that change meaning, and why prepositions always take -ing.",
 "'to do' না 'doing'? কোন verb-এর পরে কোনটা বসে, আর কোথায় অর্থ বদলায়, তা শিখুন।",[u1,u2,u3],
 [C("Ending a cover letter.","I look forward to ___ the opportunity to discuss my application.",["having","have","had","be having"],"having","Look forward to + -ing."),
  C("A colleague's habit.","He keeps ___ late to meetings.",["coming","to come","come","came"],"coming","Keep + -ing."),
  T("Travel plans.","We've decided ___ (fly) to Chattogram instead of taking the bus.","fly",["to fly"],"Decide + to."),
  F("Pick the correct sentence.",["Don't forget sending the invoice today.","Don't forget to send the invoice today.","Don't forget send the invoice today.","Don't forget for sending the invoice today."],"Don't forget to send the invoice today.","A task: forget + to."),
  B("সে আমাকে রিপোর্টটা দেখতে বলেছে।",["She asked me to check the report.","She asked me checking the report.","She asked that I to check the report.","She asked me for check the report."],"She asked me to check the report.","Ask + person + to."),
  C("Fixing a problem.","If the app crashes, try ___ the cache.",["clearing","to clear","clear","cleared"],"clearing","Test a solution: try + -ing.",True),
  C("Health.","My uncle has stopped ___ since his heart surgery.",["smoking","to smoke","smoke","smoked"],"smoking","Quit: stop + -ing."),
  F("Pick the correct sentence.",["She's good at to explain things.","She's good at explaining things.","She's good in explain things.","She's good at explain things."],"She's good at explaining things.","Preposition + -ing.")],
 [("Is the verb straight after a preposition (in, at, for, without, look forward to)?","Use -ing.","Go on."),
  ("Is it stop, remember, forget or try?","Decide the meaning: task or attempt = to; memory, quitting or testing = -ing.","Go on."),
  ("Is it a verb of liking, avoiding or finishing (enjoy, avoid, mind, finish, suggest, keep)?","Use -ing.","Plans, wishes and decisions (want, decide, hope, plan, refuse): to + base.")])
